<?php
namespace App\Http\Controllers;use App\Models\Result;use App\Models\Student;use App\Models\Subject;use App\Services\Tenant;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class ResultController {
 public function index():View{$school=Tenant::current();return view('results.index',['results'=>Result::whereBelongsTo($school)->with(['student','subject'])->latest()->paginate(30),'students'=>Student::whereBelongsTo($school)->orderBy('last_name')->get(),'subjects'=>Subject::where('school_id',$school->id)->orderBy('display_order')->get()]);}
 public function store(Request $request):RedirectResponse{$school=Tenant::current();$data=$request->validate(['student_id'=>['required','exists:students,id'],'subject_id'=>['required','exists:subjects,id'],'first_ca'=>['required','numeric','between:0,20'],'second_ca'=>['required','numeric','between:0,20'],'exam'=>['required','numeric','between:0,60'],'first_term'=>['nullable','numeric','between:0,100'],'second_term'=>['nullable','numeric','between:0,100']]);abort_unless(Student::where('school_id',$school->id)->whereKey($data['student_id'])->exists()&&Subject::where('school_id',$school->id)->whereKey($data['subject_id'])->exists(),404);Result::updateOrCreate(['school_id'=>$school->id,'student_id'=>$data['student_id'],'subject_id'=>$data['subject_id']],$data+['school_id'=>$school->id]);return back()->with('success','Result saved and graded automatically.');}
}
